cat playwright.config.ts | head -30; (npm start >$TMPDIR/s.log 2>&1 &); sleep 2; cat > $TMPDIR/shot.js <<'EOF'
const { chromium } = require('playwright');
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1200,height:800}});
const errs=[];p.on('console',m=>m.type()==='error'&&errs.push(m.text()));p.on('requestfailed',r=>errs.push('FAIL '+r.url()));p.on('response',r=>r.status()>=400&&errs.push(r.status()+' '+r.url()));
for(const n of ['index','products']){await p.goto(`http://127.0.0.1:${process.env.PORT}/${n}.html`);await p.waitForTimeout(500);await p.screenshot({path:`${process.env.TMPDIR}/${n}.png`,fullPage:true});}
console.log(errs);await b.close()})();
EOF
cp $TMPDIR/shot.js ./shot.tmp.js && node shot.tmp.js; rm shot.tmp.js

